{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "Preventable medication-related problems intensify the risk associated with cancer care and no data was available to represent the burden of medication-related problems among cancer patients in Ethiopia.",
      "reason": "The current knowledge gap is described (no available data on burden in Ethiopia), but specific “important uncertainties” and broader current-state-of-knowledge beyond this gap are not clearly detailed."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Preventable medication-related problems intensify the risk associated with cancer care and no data was available to represent the burden of medication-related problems among cancer patients in Ethiopia. Hence, this study was aimed to estimate the pooled prevalence of medication-related problems and identify its predictors among cancer patients treated in Ethiopia.",
      "reason": "The importance/need is explained via the clinical risk and the absence of data, followed by stating the study’s aim to address that need."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence was provided describing similar systematic reviews, or explaining why this review is needed in light of prior reviews/updates/replications."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_4",
      "quote": "We included observational studies conducted in Ethiopia that reported on the types, frequency, or risk factors of medication-related problems in cancer patients.",
      "reason": "The review concerns prevalence/risk factors from observational studies and does not describe an intervention effect; therefore a mechanism of action for an intervention is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_4",
      "quote": "We included observational studies conducted in Ethiopia that reported on the types, frequency, or risk factors of medication-related problems in cancer patients.",
      "reason": "There is no intervention/delivery context described in the retrieved evidence (it is an observational prevalence/risk-factor review), so a logic model of hypothesised intervention-outcome relationships is not applicable."
    }
  ],
  "confidence": 67
}

